mapper.select:
SELECT ,
        AS distance
FROM tb_ai_document_chunk


    AND object_type = #{objectType,jdbcType=VARCHAR}


    AND object_id = #{objectId,jdbcType=VARCHAR}



ORDER BY  ASC
LIMIT #{limit}

SELECT ,
        AS distance,
       ts_rank_cd(to_tsvector('simple', text || ' ' || COALESCE(metadata->>'keywordsText','')), plainto_tsquery(#{query,jdbcType=VARCHAR})) AS bm25,
       ( * #{vectorWeight})
         - (COALESCE(ts_rank_cd(to_tsvector('simple', text || ' ' || COALESCE(metadata->>'keywordsText','')), plainto_tsquery(#{query,jdbcType=VARCHAR})), 0) * #{lexicalWeight}) AS hybrid
FROM tb_ai_document_chunk


    AND object_type = #{objectType,jdbcType=VARCHAR}


    AND object_id = #{objectId,jdbcType=VARCHAR}



ORDER BY hybrid ASC
LIMIT #{limit}

SELECT COUNT(*)
FROM tb_ai_document_chunk
WHERE object_type = #{objectType,jdbcType=VARCHAR}
  AND object_id = #{objectId,jdbcType=VARCHAR}

SELECT id, object_id, text, metadata, NULL::double precision AS distance
FROM tb_ai_document_chunk
WHERE object_type = #{objectType,jdbcType=VARCHAR}
  AND (CAST(#{objectId,jdbcType=VARCHAR} AS varchar) IS NULL OR object_id = CAST(#{objectId,jdbcType=VARCHAR} AS varchar))
ORDER BY object_id, chunk_index
LIMIT #{limit}

SELECT id, object_id, text, metadata, NULL::double precision AS distance
FROM tb_ai_document_chunk
WHERE object_type = #{objectType,jdbcType=VARCHAR}
  AND (CAST(#{objectId,jdbcType=VARCHAR} AS varchar) IS NULL OR object_id = CAST(#{objectId,jdbcType=VARCHAR} AS varchar))
ORDER BY object_id, chunk_index
LIMIT #{limit} OFFSET #{offset}

SELECT id, object_id, text, metadata, NULL::double precision AS distance
FROM tb_ai_document_chunk
WHERE object_type = #{objectType,jdbcType=VARCHAR}
  AND (CAST(#{objectId,jdbcType=VARCHAR} AS varchar) IS NULL OR object_id = CAST(#{objectId,jdbcType=VARCHAR} AS varchar))

ORDER BY object_id, chunk_index
LIMIT #{limit} OFFSET #{offset}

SELECT metadata
FROM tb_ai_document_chunk
WHERE object_type = #{objectType,jdbcType=VARCHAR}
  AND object_id = #{objectId,jdbcType=VARCHAR}
ORDER BY chunk_index
LIMIT 1
